 * - get(key) returns the value and marks it most recently used; expired entries count as missing.
 * - set(key, value) inserts or updates, evicting the least recently used entry when over capacity.
 * - size counts live (unexpired) entries.
 * Throw a RangeError for a capacity below 1 (or not an integer).
 */
class LruCache<K, V> {
  constructor(capacity: number, ttlMs = Infinity, now: () => number = Date.now) {
    // TODO: set up state
  }

  get(key: K): V | undefined {
    throw new Error('Not implemented');
  }

  set(key: K, value: V): void {
    throw new Error('Not implemented');
  }

  get size(): number {
    throw new Error('Not implemented');
  }
}

p-lru-cache-with-a-ttl.solution:
class LruCache<K, V> {
  private entries = new Map<K, { value: V; expiresAt: number }>();
  private readonly capacity: number;
  private readonly ttlMs: number;
  private readonly now: () => number;

  constructor(capacity: number, ttlMs = Infinity, now: () => number = Date.now) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new RangeError('capacity must be a positive integer');
    this.capacity = capacity;
    this.ttlMs = ttlMs;
    this.now = now;
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    this.entries.delete(key);
    if (entry.expiresAt <= this.now()) return undefined; // expired: dropped
    this.entries.set(key, entry); // move to most recently used
    return entry.value;
  }

  set(key: K, value: V): void {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: this.now() + this.ttlMs });
    while (this.entries.size > this.capacity) {
      const oldest = this.entries.keys().next().value as K;
      this.entries.delete(oldest);
    }
  }

  get size(): number {
    return this.entries.size;
  }
}

p-lru-cache-with-a-ttl.tests:
let clock = 0;
const cache = new LruCache<string, number>(2, 1_000, () => clock);
cache.set('a', 1);
cache.set('b', 2);
assert.equal(cache.get('a'), 1);
 // a is now most recent
cache.set('c', 3);
 // evicts b, the least recently used
assert.equal(cache.get('b'), undefined);
assert.equal(cache.get('a'), 1);
assert.equal(cache.get('c'), 3);
cache.set('a', 10);
 // update moves it to the end
assert.equal(cache.get('a'), 10);
assert.equal(cache.size, 2);
clock = 1_000;
 // TTL reached
assert.equal(cache.get('a'), undefined);
assert.equal(cache.size, 1);
assert.throws(() => new LruCache(0), RangeError);
assert.throws(() => new LruCache(Number.NaN), RangeError);

