class PubSub<T> {
  /** Register a handler for a pattern; returns a function that unsubscribes it. */
  subscribe(pattern: string, handler: Handler<T>): () => void {
    throw new Error('Not implemented');
  }

  /** Deliver to every matching handler; one failing handler must not stop the others. Returns how many ran. */
