p-deep-merge-without-prototype-pollution.starter:
type Plain = Record<string, unknown>;

/**
 * Merge source into a COPY of target: nested plain objects merge recursively, arrays and other values replace,
 * undefined in source keeps the target's value. Never write __proto__, constructor or prototype keys.
 */
function deepMerge<T extends Plain>(target: T, source: Plain): T {
  throw new Error('Not implemented');
}

p-deep-merge-without-prototype-pollution.solution:
type Plain = Record<string, unknown>;
const isPlain = (v: unknown): v is Plain => typeof v === 'object' && v !== null && Object.getPrototypeOf(v) === Object.prototype;
const UNSAFE = new Set(['__proto__', 'constructor', 'prototype']);
function deepMerge<T extends Plain>(target: T, source: Plain): T {
  const out: Plain = { ...target };
  for (const key of Object.keys(source)) {
    if (UNSAFE.has(key)) continue;
    const next = source[key];
    if (next === undefined) continue;
    const current = out[key];
    out[key] = isPlain(current) && isPlain(next) ? deepMerge(current, next) : next;
  }
  return out as T;
}

