type Match = { name: string; params: Record<string, string> };

/**
 * add(name, pattern) registers "/runs/:runId/steps/:stepId" style routes ("*" as the last segment captures the rest).
 * match(url) ignores the query string and trailing slashes, decodes parameters, and returns the first match or null.
 */
class Router {
  add(name: string, pattern: string): this {
    throw new Error('Not implemented');
  }

  match(url: string): Match | null {
    throw new Error('Not implemented');
  }
}

p-route-matcher-with-parameters.solution:
type Match = { name: string; params: Record<string, string> };
class Router {
  private routes: { name: string; segments: string[] }[] = [];

  add(name: string, pattern: string): this {
    this.routes.push({ name, segments: pattern.split('/').filter(Boolean) });
    return this;
  }

  match(url: string): Match | null {
    const path = url.split(/[?#]/, 1)[0];
    const parts = path.split('/').filter(Boolean);
    for (const route of this.routes) {
      const params: Record<string, string> = {};
      let matched = true;
      for (let i = 0; i < route.segments.length; i++) {
        const seg = route.segments[i];
        if (seg === '*') {
          params['*'] = parts.slice(i).map(decodeURIComponent).join('/');
          return { name: route.name, params };
        }
        if (i >= parts.length) {
          matched = false;
          break;
        }
        if (seg.startsWith(':')) params[seg.slice(1)] = decodeURIComponent(parts[i]);
        else if (seg !== parts[i]) {
          matched = false;
          break;
        }
      }
      if (matched && route.segments.length === parts.length) return { name: route.name, params };
    }
    return null;
  }
}

