p-read-every-page-from-a-cursor-paginate.starter:
type Page<T> = { items: T[]; nextCursor: string | null };

/**
 * Yield every item from a cursor-paginated API, fetching a page only when the consumer needs it.
 * Stop at nextCursor === null; throw if a cursor repeats or more than maxPages pages are fetched.
 */
async function* paginate<T>(fetchPage: (cursor: string | null) => Promise<Page<T>>, { maxPages = 1_000 } = {}): AsyncGenerator<T> {
  throw new Error('Not implemented');
}

p-read-every-page-from-a-cursor-paginate.solution:
type Page<T> = { items: T[]; nextCursor: string | null };
async function* paginate<T>(fetchPage: (cursor: string | null) => Promise<Page<T>>, { maxPages = 1_000 } = {}): AsyncGenerator<T> {
  let cursor: string | null = null;
  const seen = new Set<string>();
  for (let page = 0; page < maxPages; page++) {
    const { items, nextCursor } = await fetchPage(cursor);
    yield* items;
    if (nextCursor === null) return;
    if (seen.has(nextCursor)) throw new Error(`cursor ${nextCursor} repeated`);
    seen.add(nextCursor);
    cursor = nextCursor;
  }
}

